<?php
declare(strict_types=1);
require dirname(__DIR__).'/app/bootstrap.php';
if (!is_file(BASE_PATH.'/storage/installed.lock')) redirect('../install/');
if (empty($_SESSION['admin_id']) && (($_SESSION['staff_role'] ?? '') !== 'manager')) redirect('./');
require_permission('maintenance.manage');
$pdo=db();
$report=SystemHealth::inspect($pdo);
$migrations=[];
if (db_table_exists($pdo,'app_migrations')) {
    $migrations=$pdo->query('SELECT migration_key,version,description,executed_at FROM app_migrations ORDER BY id DESC LIMIT 30')->fetchAll();
}
$versionSetting=setting('app_version','Bilinmiyor');
$okCount=count(array_filter($report['tables']))+count(array_filter($report['folders']));
$totalCount=count($report['tables'])+count($report['folders']);
?><!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sistem Merkezi</title><style>
:root{--bg:#f4f6fb;--panel:#fff;--ink:#151b2b;--muted:#697386;--line:#e6eaf2;--accent:#6d5dfc;--green:#11875d;--red:#c53b4a}*{box-sizing:border-box}body{margin:0;font-family:Inter,system-ui,-apple-system,"Segoe UI",sans-serif;background:var(--bg);color:var(--ink)}.shell{max-width:1200px;margin:auto;padding:28px}.top{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:20px}.back{color:var(--accent);text-decoration:none;font-weight:750}.hero{background:linear-gradient(135deg,#111827,#253653);color:#fff;border-radius:24px;padding:28px;display:grid;grid-template-columns:1fr auto;align-items:center;box-shadow:0 18px 45px #11182722}.hero h1{margin:0 0 8px;font-size:30px}.hero p{margin:0;color:#c8d1df}.badge{padding:10px 15px;border-radius:999px;background:#ffffff16;border:1px solid #ffffff22;font-weight:850}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:15px;margin-top:17px}.card{background:var(--panel);border:1px solid var(--line);border-radius:18px;padding:19px;box-shadow:0 8px 28px #1f293708;margin-bottom:16px}.metric{font-size:27px;font-weight:850}.label{font-size:12px;color:var(--muted);margin-top:5px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.head{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px}.head h2{font-size:17px;margin:0}.status{font-size:12px;font-weight:800;padding:5px 9px;border-radius:999px}.ok{background:#e9f9f2;color:var(--green)}.bad{background:#fff0f2;color:var(--red)}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:11px;border-bottom:1px solid var(--line);font-size:13px}th{font-size:11px;color:var(--muted);text-transform:uppercase}.dot{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:7px;background:var(--green)}.dot.bad{background:var(--red)}.muted{color:var(--muted);font-size:13px}.progress{height:9px;background:#edf0f6;border-radius:99px;overflow:hidden;margin-top:13px}.progress span{display:block;height:100%;background:linear-gradient(90deg,#6d5dfc,#8b7cff)}@media(max-width:850px){.cards{grid-template-columns:1fr 1fr}.grid{grid-template-columns:1fr}.hero{grid-template-columns:1fr;gap:18px}.shell{padding:16px}} </style><link rel="stylesheet" href="assets/admin-premium.css?v=310"></head><body><main class="shell"><div class="top"><a class="back" href="./?page=dashboard">← Yönetim paneline dön</a><strong><?=e(setting('business_name','Restoran'))?></strong></div><section class="hero"><div><h1>Sistem Merkezi</h1><p>LTS sürüm, veritabanı migration geçmişi ve sistem bütünlüğü tek ekranda.</p></div><div class="badge"><?=e(app_release_label())?></div></section><section class="cards"><div class="card"><div class="metric"><?=e($versionSetting)?></div><div class="label">Kurulu veritabanı sürümü</div></div><div class="card"><div class="metric"><?=e(PHP_VERSION)?></div><div class="label">PHP sürümü</div></div><div class="card"><div class="metric"><?=$okCount?> / <?=$totalCount?></div><div class="label">Başarılı bütünlük kontrolü</div></div><div class="card"><div class="metric" style="color:<?=$report['healthy']?'var(--green)':'var(--red)'?>"><?=$report['healthy']?'Sağlıklı':'Kontrol gerekli'?></div><div class="label">Genel sistem durumu</div></div></section><div class="grid"><section class="card"><div class="head"><h2>Veritabanı tabloları</h2><span class="status <?=$report['healthy']?'ok':'bad'?>">Şema kontrolü</span></div><table><?php foreach($report['tables'] as $name=>$ok):?><tr><td><span class="dot <?=$ok?'':'bad'?>"></span><?=e($name)?></td><td style="text-align:right"><?=$ok?'Hazır':'Eksik'?></td></tr><?php endforeach;?></table></section><section class="card"><div class="head"><h2>Sunucu ve dosya sistemi</h2><span class="status <?=$report['healthy']?'ok':'bad'?>">Canlı kontrol</span></div><table><tr><td>PDO MySQL</td><td style="text-align:right"><?=$report['pdo_mysql']?'Hazır':'Eksik'?></td></tr><tr><td>Mbstring</td><td style="text-align:right"><?=$report['mbstring']?'Hazır':'Eksik'?></td></tr><tr><td>JSON</td><td style="text-align:right"><?=$report['json']?'Hazır':'Eksik'?></td></tr><tr><td>GZIP</td><td style="text-align:right"><?=$report['gzip']?'Hazır':'Opsiyonel'?></td></tr><?php foreach($report['folders'] as $name=>$ok):?><tr><td><?=e($name)?> yazılabilir</td><td style="text-align:right"><?=$ok?'Evet':'Hayır'?></td></tr><?php endforeach;?></table><div class="progress"><span style="width:<?=round($okCount/max(1,$totalCount)*100)?>%"></span></div></section></div><section class="card"><div class="head"><h2>Migration geçmişi</h2><span class="status ok"><?=count($migrations)?> kayıt</span></div><div style="overflow:auto"><table><tr><th>Tarih</th><th>Sürüm</th><th>Migration</th><th>Açıklama</th></tr><?php foreach($migrations as $m):?><tr><td><?=e(date('d.m.Y H:i',strtotime($m['executed_at'])))?></td><td><?=e($m['version'])?></td><td><?=e($m['migration_key'])?></td><td><?=e($m['description'])?></td></tr><?php endforeach;?><?php if(!$migrations):?><tr><td colspan="4" class="muted">Henüz migration geçmişi bulunmuyor.</td></tr><?php endif;?></table></div></section><p class="muted">Bu ekran yalnızca sistem durumunu görüntüler; hiçbir veriyi silmez veya değiştirmez.</p></main><script src="assets/admin-premium.js?v=310"></script></body></html>
